/*
 * A301915  a(n) is the multiplicative order of 3, modulo A301913(n).
 * https://oeis.org/A301915
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = ord_{A301913(n)}(3), the multiplicative order of 3 modulo
 *            A301913(n). A301913 is generated by sieving primes p with -2 in
 *            <3> mod p, i.e. (-2)^ord_p(3) == 1 (mod p)
 * Range:     u8 n <= 33, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Validated: partial, pass, 55 terms through n = 55 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

static uint64_t A301915_powmod(uint64_t b, uint64_t e, uint64_t m)
{
    uint64_t r = 1 % m;
    b %= m;
    while (e) {
        if (e & 1) r = (uint64_t)(((unsigned __int128)r * b) % m);
        b = (uint64_t)(((unsigned __int128)b * b) % m);
        e >>= 1;
    }
    return r;
}

static uint64_t A301915_ord3(uint64_t p, const uint64_t *primes, size_t cnt)
{
    uint64_t ord = p - 1, rem = p - 1;
    for (size_t i = 0; i < cnt && primes[i] * primes[i] <= rem; ++i) {
        uint64_t q = primes[i];
        if (rem % q) continue;
        while (rem % q == 0) rem /= q;
        while (ord % q == 0 && A301915_powmod(3, ord / q, p) == 1) ord /= q;
    }
    if (rem > 1)
        while (ord % rem == 0 && A301915_powmod(3, ord / rem, p) == 1) ord /= rem;
    return ord;
}

seq_t a(idx_t n)
{
    static uint64_t *primes = NULL;
    static size_t pcnt = 0, pcap = 0;
    static uint64_t *ords = NULL;
    static size_t ocnt = 0, ocap = 0;
    static uint64_t cand = 5;

    if (primes == NULL) {
        pcap = 1024;
        primes = (uint64_t *)malloc(pcap * sizeof(uint64_t));
        primes[0] = 2; primes[1] = 3; pcnt = 2;
    }
    while (ocnt < (size_t)n) {
        bool isp = true;
        for (size_t i = 0; i < pcnt && primes[i] * primes[i] <= cand; ++i)
            if (cand % primes[i] == 0) { isp = false; break; }
        if (isp) {
            if (pcnt == pcap) {
                pcap *= 2;
                primes = (uint64_t *)realloc(primes, pcap * sizeof(uint64_t));
            }
            primes[pcnt++] = cand;
            uint64_t o = A301915_ord3(cand, primes, pcnt);
            if (A301915_powmod(cand - 2, o, cand) == 1) {
                if (ocnt == ocap) {
                    ocap = ocap ? ocap * 2 : 256;
                    ords = (uint64_t *)realloc(ords, ocap * sizeof(uint64_t));
                }
                ords[ocnt++] = o;
            }
        }
        cand += 2;
    }
    return (seq_t)ords[n - 1];
}
